use windows::Win32::Foundation::{ERROR_ACCESS_DENIED, ERROR_FILE_NOT_FOUND, ERROR_INVALID_PARAMETER};
use windows::Win32::NetworkManagement::IpHelper::{
    GetIpInterfaceEntry, SetIpInterfaceEntry, MIB_IPINTERFACE_ROW,
};
use windows::Win32::Networking::WinSock::{ADDRESS_FAMILY, AF_INET};

/// Sets a manual metric (`Some(n)`) or restores automatic metric (`None`) for ONE
/// address family on ONE interface. Caller must run elevated (SetIpInterfaceEntry
/// requires an elevated Administrator token; see privilege notes below).
pub fn set_interface_metric(
    if_index: u32,
    family: ADDRESS_FAMILY,
    metric: Option<u32>,
) -> windows::core::Result<()> {
    let mut row = MIB_IPINTERFACE_ROW::default(); // core::mem::zeroed()
    row.Family = family;
    row.InterfaceIndex = if_index;

    // Get first: this is how you obtain a valid, fully-populated row to mutate.
    // Get needs NO privilege (verified unelevated on real adapters).
    unsafe { GetIpInterfaceEntry(&mut row) }.ok()?;

    match metric {
        Some(m) => {
            row.UseAutomaticMetric = false; // plain `bool` field, not BOOL/BOOLEAN
            row.Metric = m;
        }
        None => {
            row.UseAutomaticMetric = true; // Metric is then stack-computed & ignored by Set
        }
    }

    // THE TRAP (learn.microsoft.com/.../nf-netioapi-setipinterfaceentry, stated twice):
    // "for IPv4, an application must not try to modify the SitePrefixLength member...
    //  the SitePrefixLength member must be set to 0." Get just filled it with a REAL
    // value (64 observed on this machine's loopback) — passing that straight to Set
    // fails with ERROR_INVALID_PARAMETER (87). NOT required/mentioned for AF_INET6.
    if family == AF_INET {
        row.SitePrefixLength = 0;
    }

    unsafe { SetIpInterfaceEntry(&mut row) }.ok()
}

/// LinkSwitch's actual need: steer BOTH IPv4 and IPv6 for one interface in one call,
/// since AF_INET and AF_INET6 are independent MIB_IPINTERFACE_ROW rows.
pub fn steer_interface(if_index: u32, metric: Option<u32>) -> windows::core::Result<()> {
    use windows::Win32::Networking::WinSock::AF_INET6;
    set_interface_metric(if_index, AF_INET, metric)?;
    set_interface_metric(if_index, AF_INET6, metric)?;
    Ok(())
}

/// Map the WIN32_ERROR a caller is most likely to see back to something actionable.
pub fn explain(e: windows::core::Error) -> &'static str {
    let code = windows::Win32::Foundation::WIN32_ERROR(e.code().0 as u32);
    if code == ERROR_ACCESS_DENIED {
        "not elevated: SetIpInterfaceEntry requires an elevated Administrator token"
    } else if code == ERROR_FILE_NOT_FOUND {
        "no such InterfaceIndex/InterfaceLuid on this machine"
    } else if code == ERROR_INVALID_PARAMETER {
        "bad Family, or (for IPv4) SitePrefixLength wasn't reset to 0 before Set"
    } else {
        "see FormatMessage / windows::core::Error::message() for the exact string"
    }
}

use windows::Win32::NetworkManagement::IpHelper::{
    FreeMibTable, GetIpInterfaceTable, MIB_IPINTERFACE_TABLE,
};
use windows::Win32::Networking::WinSock::AF_UNSPEC;

pub fn list_interfaces() -> windows::core::Result<()> {
    unsafe {
        let mut table_ptr: *mut MIB_IPINTERFACE_TABLE = std::ptr::null_mut();
        // AF_UNSPEC returns both IPv4 (Family=2) and IPv6 (Family=23) rows together.
        GetIpInterfaceTable(AF_UNSPEC, &mut table_ptr).ok()?;

        let num_entries = (*table_ptr).NumEntries as usize;
        // Table: [MIB_IPINTERFACE_ROW; 1] is windows-rs's rendering of a C
        // ANYSIZE_ARRAY flexible-array member. `.Table[i]` for i >= 1 panics
        // (fixed compile-time length 1) — always walk it as a raw pointer.
        let rows_ptr = (*table_ptr).Table.as_ptr();
        for i in 0..num_entries {
            let row = &*rows_ptr.add(i);
            println!(
                "ifIndex={} family={} metric={} auto={}",
                row.InterfaceIndex, row.Family.0, row.Metric, row.UseAutomaticMetric
            );
        }

        FreeMibTable(table_ptr as *const core::ffi::c_void);
    }
    Ok(())
}

