use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use windows::Win32::Foundation::ERROR_BUFFER_OVERFLOW;
use windows::Win32::NetworkManagement::IpHelper::{
    GetAdaptersAddresses, IP_ADAPTER_ADDRESSES_LH,
    GAA_FLAG_SKIP_ANYCAST, GAA_FLAG_SKIP_MULTICAST, GAA_FLAG_SKIP_DNS_SERVER,
    GAA_FLAG_INCLUDE_PREFIX, GAA_FLAG_INCLUDE_GATEWAYS,
};
use windows::Win32::Networking::WinSock::{AF_UNSPEC, AF_INET, AF_INET6, SOCKADDR, SOCKADDR_IN, SOCKADDR_IN6};

pub struct Adapter {
    pub friendly_name: String,
    pub description: String,
    pub if_type: u32,
    pub if_index: u32,
    pub luid: windows::Win32::NetworkManagement::Ndis::NET_LUID_LH,
    pub oper_up: bool,
    pub tx_link_speed: u64,
    pub rx_link_speed: u64,
    pub unicast_ips: Vec<IpAddr>,
    pub gateway_ips: Vec<IpAddr>,
    pub dns_suffix: String,
}

unsafe fn sockaddr_to_ip(sa: *const SOCKADDR) -> Option<IpAddr> {
    if sa.is_null() { return None; }
    match (*sa).sa_family {
        AF_INET => Some(IpAddr::V4(Ipv4Addr::from((*(sa as *const SOCKADDR_IN)).sin_addr))),
        AF_INET6 => Some(IpAddr::V6(Ipv6Addr::from((*(sa as *const SOCKADDR_IN6)).sin6_addr))),
        _ => None,
    }
}

unsafe fn pwstr_to_string(p: windows::core::PWSTR) -> String {
    if p.is_null() { return String::new(); }
    p.to_string().unwrap_or_default()
}

pub fn enum_adapters() -> windows::core::Result<Vec<Adapter>> {
    const MAX_TRIES: u32 = 3; // Microsoft's own sample: start at 15KB, retry only on overflow.
    let flags = GAA_FLAG_SKIP_ANYCAST | GAA_FLAG_SKIP_MULTICAST | GAA_FLAG_SKIP_DNS_SERVER
        | GAA_FLAG_INCLUDE_PREFIX | GAA_FLAG_INCLUDE_GATEWAYS;

    let mut buf_len: u32 = 15_000;
    let mut buffer: Vec<u8>;
    let mut ret: u32;
    let mut tries = 0u32;
    loop {
        buffer = vec![0u8; buf_len as usize];
        let ptr = buffer.as_mut_ptr() as *mut IP_ADAPTER_ADDRESSES_LH;
        ret = unsafe {
            GetAdaptersAddresses(AF_UNSPEC.0 as u32, flags, None, Some(ptr), &mut buf_len)
        };
        tries += 1;
        if ret != ERROR_BUFFER_OVERFLOW.0 || tries >= MAX_TRIES { break; }
    }
    if ret != 0 /* ERROR_SUCCESS */ {
        return Err(windows::core::Error::from(windows::Win32::Foundation::WIN32_ERROR(ret)));
    }

    let mut out = Vec::new();
    let mut cur = buffer.as_ptr() as *const IP_ADAPTER_ADDRESSES_LH;
    while !cur.is_null() {
        let a = unsafe { &*cur };
        let mut unicast_ips = Vec::new();
        let mut p = a.FirstUnicastAddress;
        while !p.is_null() {
            let ua = unsafe { &*p };
            if let Some(ip) = unsafe { sockaddr_to_ip(ua.Address.lpSockaddr) } { unicast_ips.push(ip); }
            p = ua.Next;
        }
        let mut gateway_ips = Vec::new();
        let mut g = a.FirstGatewayAddress;
        while !g.is_null() {
            let ga = unsafe { &*g };
            if let Some(ip) = unsafe { sockaddr_to_ip(ga.Address.lpSockaddr) } { gateway_ips.push(ip); }
            g = ga.Next;
        }
        out.push(Adapter {
            friendly_name: unsafe { pwstr_to_string(a.FriendlyName) },
            description: unsafe { pwstr_to_string(a.Description) },
            if_type: a.IfType,
            if_index: unsafe { a.Anonymous1.Anonymous.IfIndex }, // union: IfIndex or Length, per LH layout -- CONFIRM path against installed crate version, see open_questions
            luid: a.Luid,
            oper_up: a.OperStatus == windows::Win32::NetworkManagement::Ndis::IfOperStatusUp,
            tx_link_speed: a.TransmitLinkSpeed,
            rx_link_speed: a.ReceiveLinkSpeed,
            unicast_ips,
            gateway_ips,
            dns_suffix: unsafe { pwstr_to_string(a.DnsSuffix) },
        });
        cur = a.Next;
    }
    Ok(out)
}

use windows::Win32::NetworkManagement::IpHelper::{
    GetIfEntry2, MIB_IF_ROW2, IF_TYPE_ETHERNET_CSMACD, IF_TYPE_IEEE80211,
    IF_TYPE_TUNNEL, IF_TYPE_SOFTWARE_LOOPBACK, IF_TYPE_PPP,
};
use windows::Win32::NetworkManagement::Ndis::NET_LUID_LH;

const HARDWARE_INTERFACE_BIT: u8 = 0x01; // InterfaceAndOperStatusFlags bit 0 (MSVC bitfield, LSB first)

pub fn is_real_hardware_nic(luid: NET_LUID_LH, if_type: u32) -> bool {
    if if_type == IF_TYPE_TUNNEL || if_type == IF_TYPE_SOFTWARE_LOOPBACK || if_type == IF_TYPE_PPP {
        return false; // cheap reject before the syscall
    }
    if if_type != IF_TYPE_ETHERNET_CSMACD && if_type != IF_TYPE_IEEE80211 {
        return false; // only care about real Ethernet/Wi-Fi for LinkSwitch's purposes
    }
    let mut row = MIB_IF_ROW2::default();
    row.InterfaceLuid = luid;
    if unsafe { GetIfEntry2(&mut row) } != windows::Win32::Foundation::WIN32_ERROR(0) {
        return false;
    }
    (row.InterfaceAndOperStatusFlags._bitfield & HARDWARE_INTERFACE_BIT) != 0
}
// NOTE: Description-substring matching ("Virtual", "Hyper-V", "VMware", "TAP", "vEthernet",
// "Bluetooth", "WAN Miniport") is a useful *extra* belt-and-suspenders filter for edge cases
// (e.g. some USB Wi-Fi dongles or SR-IOV NICs may not set HardwareInterface consistently on
// older drivers) but should be secondary to the HardwareInterface flag, not primary.

use windows::Win32::NetworkManagement::IpHelper::{GetBestRoute2, MIB_IPFORWARD_ROW2};
use windows::Win32::Networking::WinSock::{SOCKADDR_INET, AF_INET, SOCKADDR_IN, IN_ADDR};

pub fn winning_interface_for(dest_v4: std::net::Ipv4Addr) -> windows::core::Result<MIB_IPFORWARD_ROW2> {
    let mut dest = SOCKADDR_INET::default();
    dest.si_family = AF_INET;
    dest.Ipv4 = SOCKADDR_IN {
        sin_family: AF_INET,
        sin_port: 0,
        sin_addr: IN_ADDR::from(dest_v4),
        sin_zero: [0; 8],
    };
    let mut best_route = MIB_IPFORWARD_ROW2::default();
    let mut best_src = SOCKADDR_INET::default();
    let err = unsafe {
        GetBestRoute2(None, 0, None, &dest, 0, &mut best_route, &mut best_src)
    };
    if err.0 != 0 { return Err(windows::core::Error::from(err)); }
    Ok(best_route) // best_route.InterfaceLuid / .InterfaceIndex is the winning NIC right now
}
// Call with dest_v4 = 8.8.8.8. This is authoritative: it's the same code path Windows itself
// uses, so it reflects effective-metric math + any policy routing you didn't think to model.
// GetIpForwardTable2 + manual (row.Metric + interface_metric) comparison is fine for a
// side-by-side diagnostics table but is a re-implementation, not a source of truth.

use std::sync::OnceLock;
use windows::Win32::Foundation::HANDLE;
use windows::Win32::NetworkManagement::IpHelper::{
    NotifyIpInterfaceChange, NotifyRouteChange2, NotifyUnicastIpAddressChange,
    CancelMibChangeNotify2, MIB_IPINTERFACE_ROW, MIB_IPFORWARD_ROW2, MIB_UNICASTIPADDRESS_ROW,
    MIB_NOTIFICATION_TYPE,
};
use windows::Win32::Networking::WinSock::AF_UNSPEC;
use std::ffi::c_void;

static REPAINT_CTX: OnceLock<egui::Context> = OnceLock::new();

// Call once from eframe::App::new / CreationContext, before registering.
pub fn install_repaint_context(ctx: egui::Context) { let _ = REPAINT_CTX.set(ctx); }

unsafe extern "system" fn on_iface_change(
    _ctx: *const c_void, _row: *const MIB_IPINTERFACE_ROW, _kind: MIB_NOTIFICATION_TYPE,
) {
    // Keep this MINIMAL: just wake the UI thread. Do the real GetAdaptersAddresses/
    // GetBestRoute2 re-query on the next egui update() frame, not here.
    if let Some(c) = REPAINT_CTX.get() { c.request_repaint(); }
}
unsafe extern "system" fn on_route_change(
    _ctx: *const c_void, _row: *const MIB_IPFORWARD_ROW2, _kind: MIB_NOTIFICATION_TYPE,
) { if let Some(c) = REPAINT_CTX.get() { c.request_repaint(); } }

unsafe extern "system" fn on_addr_change(
    _ctx: *const c_void, _row: *const MIB_UNICASTIPADDRESS_ROW, _kind: MIB_NOTIFICATION_TYPE,
) { if let Some(c) = REPAINT_CTX.get() { c.request_repaint(); } }

pub struct NotifyHandles(HANDLE, HANDLE, HANDLE);

pub fn register_all() -> windows::core::Result<NotifyHandles> {
    let mut h1 = HANDLE::default();
    let mut h2 = HANDLE::default();
    let mut h3 = HANDLE::default();
    unsafe {
        NotifyIpInterfaceChange(AF_UNSPEC, Some(on_iface_change), None, true, &mut h1).ok()?;
        NotifyRouteChange2(AF_UNSPEC, Some(on_route_change), std::ptr::null(), true, &mut h2).ok()?;
        NotifyUnicastIpAddressChange(AF_UNSPEC, Some(on_addr_change), None, true, &mut h3).ok()?;
    }
    Ok(NotifyHandles(h1, h2, h3))
}

pub fn unregister_all(h: NotifyHandles) {
    // MUST be called from a thread OTHER than one currently inside a callback for this
    // handle, or the OS deadlocks you (documented Microsoft behavior). Call this from
    // your app's normal shutdown path (eframe on_exit), never from inside on_*_change.
    unsafe {
        let _ = CancelMibChangeNotify2(h.0);
        let _ = CancelMibChangeNotify2(h.1);
        let _ = CancelMibChangeNotify2(h.2);
    }
}
// Why all three: changing OUR OWN interface metric (SetIpInterfaceEntry, in --apply) fires
// NotifyIpInterfaceChange (MibParameterNotification) but does NOT add/remove a forwarding
// row, so NotifyRouteChange2 alone would miss our own metric-steering action. Route add/
// delete (VPN connect, cable pulled) fires NotifyRouteChange2. DHCP lease / new IP on Wi-Fi
// associating fires NotifyUnicastIpAddressChange. Register all three.

use windows::Win32::NetworkManagement::WiFi::{
    WlanOpenHandle, WlanCloseHandle, WlanEnumInterfaces, WlanQueryInterface, WlanFreeMemory,
    WLAN_INTERFACE_INFO_LIST, WLAN_CONNECTION_ATTRIBUTES, wlan_intf_opcode_current_connection,
    WLAN_OPCODE_VALUE_TYPE, wlan_interface_state_connected,
};
use windows::Win32::Foundation::HANDLE;

pub struct WifiStatus { pub ssid: String, pub signal_quality_pct: u32 }

pub fn current_wifi_status() -> windows::core::Result<Option<WifiStatus>> {
    let mut handle = HANDLE::default();
    let mut negotiated = 0u32;
    unsafe { WlanOpenHandle(2, None, &mut negotiated, &mut handle) };
    // (check return != ERROR_SUCCESS in real code)
    let mut list_ptr: *mut WLAN_INTERFACE_INFO_LIST = std::ptr::null_mut();
    unsafe { WlanEnumInterfaces(handle, None, &mut list_ptr) };
    let mut result = None;
    if !list_ptr.is_null() {
        let list = unsafe { &*list_ptr };
        // list.InterfaceInfo is a flexible array member; iterate list.dwNumberOfItems entries.
        for i in 0..list.dwNumberOfItems as usize {
            let info = unsafe { &*(list.InterfaceInfo.as_ptr().add(i)) };
            if info.isState != wlan_interface_state_connected { continue; }
            let mut data_size = 0u32;
            let mut data_ptr: *mut std::ffi::c_void = std::ptr::null_mut();
            let mut opcode_type = WLAN_OPCODE_VALUE_TYPE::default();
            let ok = unsafe {
                WlanQueryInterface(handle, &info.InterfaceGuid, wlan_intf_opcode_current_connection,
                    None, &mut data_size, &mut data_ptr, Some(&mut opcode_type))
            };
            if ok == 0 && !data_ptr.is_null() {
                let attrs = unsafe { &*(data_ptr as *const WLAN_CONNECTION_ATTRIBUTES) };
                let ssid = &attrs.wlanAssociationAttributes.dot11Ssid;
                let name = String::from_utf8_lossy(&ssid.ucSSID[..ssid.uSSIDLength as usize]).into_owned();
                result = Some(WifiStatus {
                    ssid: name,
                    signal_quality_pct: attrs.wlanAssociationAttributes.wlanSignalQuality,
                });
            }
            if !data_ptr.is_null() { unsafe { WlanFreeMemory(data_ptr) }; }
            break;
        }
    }
    if !list_ptr.is_null() { unsafe { WlanFreeMemory(list_ptr as *const _) }; }
    unsafe { WlanCloseHandle(handle, None) };
    Ok(result)
}
// Complexity verdict: ~60-100 lines total, no async, no polling loop needed (call once when
// the UI needs to show SSID/bars). Worth it for a "Wi-Fi: MyNetwork bars" label; skip if you
// only need "is Wi-Fi up" (OperStatus from GetAdaptersAddresses already answers that cheaply).

added_gotchas:
CRITICAL, MISSING, AND IT WILL BREAK --apply: SetIpInterfaceEntry on IPv4 requires SitePrefixLength == 0, but GetIpInterfaceEntry HANDS YOU 64. Microsoft states it twice in the SetIpInterfaceEntry Remarks: 'However for IPv4, an application must not try to modify the SitePrefixLength member of the MIB_IPINTERFACE_ROW structure. For IPv4, the SitePrefixLength member must be set to 0.' I read it live on this machine: ifidx 4 (Ethernet) SitePrefixLength=64, ifidx 14 (Wi-Fi) SitePrefixLength=64. So the obvious read-modify-write returns ERROR_INVALID_PARAMETER (87). Correct --apply worker:

  let mut row = MIB_IPINTERFACE_ROW::default();
  row.Family = AF_INET;
  row.InterfaceLuid = luid;                       // LUID preferred over index (index is not persistent)
  unsafe { GetIpInterfaceEntry(&mut row) }.ok()?;
  row.SitePrefixLength = 0;                       // MANDATORY for AF_INET, else ERROR_INVALID_PARAMETER
  row.UseAutomaticMetric = false;                 // MANDATORY, else your Metric is ignored
  row.Metric = desired;
  unsafe { SetIpInterfaceEntry(&mut row) }.ok()?;

Do NOT apply SitePrefixLength=0 on the AF_INET6 pass — the rule is IPv4-only.

