#![windows_subsystem = "windows"]  // GUI subsystem always; console is attached manually when needed

use windows::Win32::Foundation::{HANDLE, GENERIC_READ, GENERIC_WRITE};
use windows::Win32::Storage::FileSystem::{CreateFileW, FILE_SHARE_READ, FILE_SHARE_WRITE, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL};
use windows::Win32::System::Console::{
    AttachConsole, ATTACH_PARENT_PROCESS, SetStdHandle,
    STD_OUTPUT_HANDLE, STD_ERROR_HANDLE, STD_INPUT_HANDLE,
};
use windows::core::w;

fn attach_console_if_needed() {
    let has_subcommand = std::env::args().len() > 1;
    if !has_subcommand {
        return; // plain widget launch: stay silent/consoleless
    }
    unsafe {
        // Fails harmlessly if there's no parent console (e.g. launched by Task Scheduler);
        // --apply should be logging to a file anyway in that case, not stdout.
        let _ = AttachConsole(ATTACH_PARENT_PROCESS);

        // AttachConsole alone does NOT fix std::io::stdout()/stderr() -- the process's
        // inherited std handles were already fixed (often null) at CreateProcess time.
        // Re-point them BEFORE the first println!/eprintln! call:
        if let Ok(h) = CreateFileW(w!("CONOUT$"), (GENERIC_READ | GENERIC_WRITE).0, FILE_SHARE_READ | FILE_SHARE_WRITE, None, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, None) {
            let _ = SetStdHandle(STD_OUTPUT_HANDLE, h);
            let _ = SetStdHandle(STD_ERROR_HANDLE, h);
        }
        if let Ok(h) = CreateFileW(w!("CONIN$"), (GENERIC_READ | GENERIC_WRITE).0, FILE_SHARE_READ | FILE_SHARE_WRITE, None, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, None) {
            let _ = SetStdHandle(STD_INPUT_HANDLE, h);
        }
    }
}

fn main() {
    attach_console_if_needed();
    // ... dispatch on argv: no args -> run_native(...); "--apply" -> elevated worker; etc.
}

use std::path::PathBuf;
use serde::{Serialize, Deserialize};

#[derive(Serialize, Deserialize, Default)]
struct LinkSwitchConfig {
    window_x: Option<f32>,
    window_y: Option<f32>,
    ethernet_adapter_guid: Option<String>,
    wifi_adapter_guid: Option<String>,
    last_mode: Option<String>, // "ethernet" | "wifi" | "auto"
}

fn config_path() -> PathBuf {
    // %APPDATA%\LinkSwitch\config.json -- readable/writable by the unelevated GUI AND
    // the elevated `--apply` worker, unlike eframe's own storage_dir()/persistence feature,
    // which only exists inside an eframe::run_native() call the CLI subcommands never make.
    let appdata = std::env::var("APPDATA").expect("%APPDATA%");
    PathBuf::from(appdata).join("LinkSwitch").join("config.json")
}

fn load_config() -> LinkSwitchConfig {
    std::fs::read_to_string(config_path())
        .ok()
        .and_then(|s| serde_json::from_str(&s).ok())
        .unwrap_or_default()
}

fn save_config(cfg: &LinkSwitchConfig) -> std::io::Result<()> {
    let path = config_path();
    std::fs::create_dir_all(path.parent().unwrap())?;
    std::fs::write(path, serde_json::to_string_pretty(cfg).unwrap())
}

