use windows::Win32::NetworkManagement::Ndis::NET_LUID_LH;
use windows::Win32::Networking::WinSock::{ADDRESS_FAMILY, AF_INET};

/// metric = Some(n) -> pin manual metric n; None -> hand control back to Windows.
/// REQUIRES ELEVATION (ERROR_ACCESS_DENIED otherwise).
pub fn set_iface_metric(
    luid: NET_LUID_LH,
    family: ADDRESS_FAMILY,
    metric: Option<u32>,
) -> windows::core::Result<()> {
    unsafe {
        // Read-modify-write: never hand SetIpInterfaceEntry a half-initialised row.
        let mut row = MIB_IPINTERFACE_ROW::default();
        row.Family = family;
        row.InterfaceLuid = luid;              // LUID, NOT InterfaceIndex (index is not stable)
        GetIpInterfaceEntry(&mut row).ok()?;

        match metric {
            Some(m) => { row.UseAutomaticMetric = 0; row.Metric = m; }  // BOOLEAN maps to u8
            None    => { row.UseAutomaticMetric = 1; }                  // Metric then ignored
        }

        // MANDATORY for IPv4 or the call fails / misbehaves (documented).
        if family == AF_INET { row.SitePrefixLength = 0; }

        SetIpInterfaceEntry(&mut row).ok()
    }
}

