use windows::Win32::NetworkManagement::WindowsConnectionManager::{
    WcmFreeMemory, WcmQueryProperty, wcm_global_property_minimize_policy,
};
use windows::core::PCWSTR;

/// Returns (value, is_group_policy). value: 0 allow-all, 1 minimize (OS DEFAULT),
/// 2 stay-on-cellular, 3 prevent-wifi-when-on-ethernet.
/// Anything != 0 means LinkSwitch cannot rely on Wi-Fi staying/auto-connecting.
pub fn wcm_minimize_policy() -> Option<(i32, i32)> {
    unsafe {
        let mut size: u32 = 0;
        let mut data: *mut u8 = std::ptr::null_mut();
        let rc = WcmQueryProperty(
            None,                                   // global property -> NULL interface
            PCWSTR::null(),
            wcm_global_property_minimize_policy,
            None,
            &mut size,
            &mut data,
        );
        if rc != 0 || data.is_null() || size < 8 { return None; }
        let f_value        = std::ptr::read_unaligned(data as *const i32);
        let f_is_grouppol  = std::ptr::read_unaligned(data.add(4) as *const i32);
        WcmFreeMemory(data as *mut _);
        Some((f_value, f_is_grouppol))
    }
}
