unsafe fn adapters() -> Option<(Vec<u64>, *const IP_ADAPTER_ADDRESSES_LH)> {
    let flags = GAA_FLAG_INCLUDE_GATEWAYS | GAA_FLAG_SKIP_ANYCAST | GAA_FLAG_SKIP_MULTICAST;
    let family = AF_UNSPEC.0 as u32;   // note: .0 as u32, param is a bare u32

    let mut size: u32 = 0;
    let rc = unsafe { GetAdaptersAddresses(family, flags, None, None, &mut size) };
    if rc != ERROR_BUFFER_OVERFLOW && rc != NO_ERROR_U32 { return None; }

    // Vec<u64> guarantees the 8-byte alignment IP_ADAPTER_ADDRESSES_LH requires.
    // A vec![0u8; n] is only 1-byte aligned and is UB to cast.
    let words = (size as usize).div_ceil(8) + 1;
    let mut buf: Vec<u64> = vec![0u64; words];
    let head = buf.as_mut_ptr() as *mut IP_ADAPTER_ADDRESSES_LH;

    let rc = unsafe { GetAdaptersAddresses(family, flags, None, Some(head), &mut size) };
    if rc != NO_ERROR_U32 { return None; }
    Some((buf, head as *const _))   // buf must outlive every use of head
